  hV = `Joc remarcabil cu poveste complexă`,
  gV = `Pură relaxare`,
  _V = `Nu sugera o anumită categorie, mai bine lasă-ți fanii să aleagă categoria pe care o consideră cea mai potrivită pentru titlul tău. Evenimentul va include în continuare un link către pagina nominalizărilor.`,
  vV = `Nicio categorie`,
  yV = `Poate a fost experiența captivantă pe care o oferă jocul sau povestea fascinantă, personajele sale bine concepute, designul său imaculat sau modul multiplayer care creează dependență. Oricare ar fi motivul, câștigătorul premiului „Cel mai bun joc al anului” din 2020 este un adevărat clasic.`,
  bV = `Jocul RV al anului nu este doar o replică a realității obișnuite. Acest joc îmbunătățește realitatea, profitând de mediul realității virtuale și forțând frontierele tărâmului virtual.`,
  xV = `Jocul acesta a fost lansat de ceva timp. Echipa a trecut de mult timp dincolo de debutul fructului creației lor, dar, fiind părinți buni, acești dezvoltatori continuă să-și îngrijească și să-și sprijine creația. Jocul acesta, chiar și în această zi, încă mai primește conținut nou, după toți acești ani.`,
  SV = `Sunt unele jocuri care pur și simplu nu sunt la fel când le joci singur. Poate ai nevoie de un prieten care să te asiste. Poate ai nevoie de un prieten pe care să îl înjunghii în spate. În ambele cazuri, distracția îi așteaptă pe aceia care își adună prietenii pentru a juca acest joc.`,
  CV = `Stilul vizual nu aspiră la o fidelitatea grafică aproape de realitate (chiar dacă este un țel nobil)… acesta descrie un aspect distinctiv și o senzație care predomină întregul joc.`,
  wV = `Designerii acestui joc sunt în primele linii ale experimentării creative, aducând o perspectivă nouă și surprize halucinante. Acest joc a încântat, a inspirat și a distrat publicul cu lucruri nemaivăzute până acum.`,
  TV = `Acesta este jocul care recompensează perseverența și nu este pentru cei slabi de inimă. Este cel mai dificil joc dintre titlurile noastre preferate.`,
  EV = `Acest erou necunoscut merită să fie sărbătorit pentru excepționala sa coloană sonoră, care merită pe deplin un mare și puternic BRAVO! `,
  DV = `Uneori, ai nevoie doar de un joc cu o narațiune puternică, iar acesta excelează aici. E captivant ca orice telenovelă și e la fel de precis ca o piesă de teatru. Felicitări pentru că ne-ai oferit atâtea emoții puternice!`,
  OV = `Acest joc este antidotul unei zile aglomerate. E suav, e relaxant și face grijile să se topească. Acest joc este momentul tău zen.`,
  kV = `Schimbi nominalizarea?`,
  AV = `Poți nominaliza doar un singur titlu pentru fiecare categorie și deja ai nominalizat %1$s pentru aceasta. Vrei să nominalizezi %2$s în schimb?`,
  jV = `Votează`,
  MV = `Votat`,
  NV = `Vot înregistrat`,
  PV = `Dorești să-ți schimbi votul?`,
  FV = `Poți vota doar un singur titlu pentru fiecare categorie și deja ai votat %1$s pentru aceasta. Vrei să votezi %2$s în schimb?`,
  IV = `Contul tău pare a fi limitat. Pentru a preveni abuzul de voturi, trebuie mai întâi să cheltuiești 5 USD pe Steam pentru a putea participa la Premiile Steam. %1$s pentru mai multe informații.`,
  LV = `Contul tău pare a fi limitat. Pentru a preveni abuzul de voturi, trebuie mai întâi să cheltuiești 5 USD pe Steam pentru a putea participa la Premiile Steam. %1$s pentru mai multe informații.`,
