  JV = `Poate a fost experiența captivantă pe care o oferă jocul sau povestea fascinantă, personajele sale bine concepute, designul său imaculat sau modul multi-jucător care creează dependență. Oricare ar fi motivul, câștigătorul de anul acesta al premiului „Cel mai bun joc al anului” este un adevărat clasic.`,
  YV = `Jocul RV al anului nu este doar o replică a realității obișnuite. Acest joc îmbunătățește realitatea, profitând de mediul realității virtuale și forțând frontierele tărâmului virtual.`,
  XV = `Jocul acesta a fost lansat de ceva timp. Echipa a trecut de mult timp dincolo de debutul fructului creației lor, dar, fiind părinți buni, acești dezvoltatori continuă să-și îngrijească și să-și sprijine creația. Jocul acesta, chiar și în această zi, încă mai primește conținut nou, după toți acești ani.`,
  ZV = `Sunt unele jocuri care pur și simplu nu sunt la fel când le joci singur. Poate ai nevoie de un prieten care să te asiste. Poate ai nevoie de un prieten pe care să îl înjunghii în spate. În ambele cazuri, distracția îi așteaptă pe aceia care își adună prietenii pentru a juca acest joc.`,
  QV = `Stilul vizual nu aspiră la o fidelitate grafică aproape de realitate (chiar dacă este un țel nobil)… acesta descrie un aspect distinctiv și o senzație care predomină de-a lungul întregului joc.`,
  $V = `Designerii acestui joc sunt în primele linii ale experimentării creative, oferind o perspectivă nouă și surprize halucinante. Acest joc a încântat, a inspirat și a distrat publicul cu lucruri nemaivăzute până acum.`,
  eH = `Acesta este jocul care recompensează perseverența și nu este pentru cei slabi de inimă. Este cel mai dificil joc dintre titlurile noastre preferate.`,
  tH = `Acest erou necunoscut merită să fie sărbătorit pentru excepționala sa coloană sonoră, care merită pe deplin un mare și puternic BRAVO! `,
  nH = `Uneori, ai nevoie doar de un joc cu o narațiune puternică, iar acesta excelează aici. E captivant ca orice telenovelă și e la fel de precis ca o piesă de teatru. Felicitări pentru că ne-ai oferit atâtea emoții puternice!`,
  rH = `Acest joc este antidotul unei zile aglomerate. E suav, e relaxant și face grijile să se topească. Acest joc este momentul tău zen.`,
  iH = `Jocul anului`,
  aH = `Jocul RV al anului`,
  oH = `Trudit cu drag`,
  sH = `Mai bine cu prietenii`,
  cH = `Stil vizual remarcabil`,
  lH = `Cel mai inovativ joc`,
  uH = `Cel mai bun joc la care ești varză`,
  dH = `Cea mai bună coloană sonoră`,
  fH = `Joc remarcabil cu poveste complexă`,
  pH = `Pură relaxare`,
  mH = `Cel mai bun joc pentru călătorii`,
  hH = `Poate a fost experiența captivantă pe care o oferă jocul sau povestea fascinantă, personajele sale bine concepute, designul său imaculat sau modul multi-jucător care creează dependență. Oricare ar fi motivul, câștigătorul de anul acesta al premiului „Cel mai bun joc al anului” este un adevărat clasic.`,
  gH = `Jocul RV al anului nu este doar o replică a realității obișnuite. Acest joc îmbunătățește realitatea, profitând de mediul realității virtuale și forțând frontierele tărâmului virtual.`,
  _H = `Jocul acesta a fost lansat de ceva timp. Echipa a trecut de mult timp dincolo de debutul fructului creației lor, dar, fiind părinți buni, acești dezvoltatori continuă să-și îngrijească și să-și sprijine creația. Jocul acesta, chiar și în ziua de azi, încă mai primește conținut nou, după toți acești ani.`,
  vH = `Sunt unele jocuri care pur și simplu nu sunt la fel când le joci singur. Poate ai nevoie de un prieten care să te asiste. Poate ai nevoie de un prieten pe care să îl înjunghii în spate. În ambele cazuri, distracția îi așteaptă pe aceia care își adună prietenii pentru a juca acest joc.`,
  yH = `Stilul vizual nu aspiră la o fidelitate grafică aproape de realitate (chiar dacă este un țel nobil)… acesta descrie un aspect distinctiv și o senzație care predomină de-a lungul întregului joc.`,
  bH = `Designerii acestui joc sunt în primele linii ale experimentării creative, oferind o perspectivă nouă și surprize halucinante. Acest joc a încântat, a inspirat și a distrat publicul cu lucruri nemaivăzute până acum.`,
  xH = `Acesta este jocul care recompensează perseverența și nu este pentru cei slabi de inimă. Este cel mai dificil joc dintre titlurile noastre preferate.`,
  SH = `Acest erou necunoscut merită să fie sărbătorit pentru excepționala sa coloană sonoră, care merită pe deplin un mare și puternic BRAVO! `,
  CH = `Uneori, ai nevoie doar de un joc cu o narațiune puternică, iar acesta excelează aici. E captivant ca orice telenovelă și e la fel de precis ca o piesă de teatru. Felicitări pentru că ne-ai oferit atâtea emoții puternice!`,
  wH = `Acest joc este antidotul unei zile aglomerate. E suav, e relaxant și face grijile să se topească. Acest joc este momentul tău zen.`,
  TH = `Acest joc a fost într-atât de reușit, că l-ai luat cu tine peste tot! Și, din fericire, toate caracteristicile care l-au făcut bun de jucat la nesfârșit pe desktop se dovedesc chiar mai bune atunci când ești în deplasare.`,
  EH = `Doar pentru RV`,
  DH = `Compatibilitate cu RV`,
  OH = `%1$s până la următoarea tragere aleatorie!`,
  kH = `Timpul rămas până la următoarea tragere aleatorie.`,
  AH = `Continuă să vizionezi pentru a avea o șansă de a câștiga!`,
  jH = `Tragerea aleatorie este în curs`,
  MH = `Numărul câștigătorilor norocoși de până acum!`,
  NH = `Concursul s-a încheiat. Îți mulțumim pentru participare!`,
  PH = `Concursul s-a încheiat cu %1$s câștigători norocoși. Îți mulțumim pentru participare!`,
  FH = `Apasă pentru a afla mai multe despre premii, câștigători și regulament`,
  IH = `Revino în fiecare zi pentru a primi un cadou de la împărat!`,
  LH = `Revino în fiecare zi pentru un nou capitol`,
