  eU = `MAREA CURSĂ A ÎMPĂRATULUI`,
  tU = `Originea zodiacului chinezesc`,
  nU = `Partea I din IV`,
  rU = `Partea a II-a din IV`,
  iU = `Partea a III-a din IV`,
  aU = `Partea a IV-a din IV`,
  oU = `Împăratul de Jad a chemat toate creaturile regatului ca acestea să se întreacă către palatul divin, declarând că primii doisprezece sosiți vor primi un loc de onoare în noul său calendar.

Șobolanul cel isteț a fost primul care a trecut râul spre tărâmul ceresc. Deoarece nu îi plăcea să înoate, șoarecele s-a cocoțat pe bou, care sărea cu bucurie prin grădina împăratului chiar înainte ca cei doi să ajungă la mal.

Boul cel perseverent a trecut râul cu ușurință. Cu indiferență față de rezultatul cursei, boul era fericit cu rolul său în succesul șoarecelui.`,
  sU = `Tigrul independent a călătorit cu prea mare grijă și nu l-a putut întrece pe bou, gândindu-se că e mai bine să ajungă al treilea decât deloc.

Iepurele cel ager a sărit pe un buștean care plutea foarte lent în derivă. Bafta, însă, a fost de partea sa, iar o briză utilă i-a zorit barca improvizată spre destinație.

Dragonul zburător a văzut un sat aflat în primejdie, iar dragonul s-a oprit desigur pentru a sări în ajutor, dăruind chiar iepurelui o rafală care să-l ajute să treacă râul. Onoarea era cu mult mai importantă spre deosebire de victorie, iar dragonul a considerat că locul al cincilea este unul adecvat.`,
  cU = `Șarpele pus pe furișat nu dorea să depună eforturi semnificative, așa că s-a încolăcit și s-a ascuns pe copita din față a calului.

În timp ce calul galopa spre linia de final, șarpele și-a dat drumul, speriind calul suficient cât să obțină locul al șaselea, calul venind timid din spate la o distanță scurtă.`,
  lU = `Capra, maimuța și cocoșul au lucrat în echipă, dar au lăsat capra să obțină locul al optulea datorită rolului semnificativ în călătoria lor. Maimuța veselă a fost următoarea, iar cocoșul a mers trufaș înainte, mândru că ordinea era corectă.

Câinele jucăuș a fost preocupat cu bălăceală, iar astfel a ajuns pe locul al unsprezecelea, dar s-a distrat.

Pe ultimul loc a sosit porcul, care s-a oprit pentru mâncare și somn, știind bine că fiecare animal va fi la rând pentru favoarea împăratului.`,
  uU = `Modificările de profil devin efective după verificare`,
